  "tripletSingleCell": "2",
  "tripletThreeCell": "_3'",
  "groupTwo": "_2'",
  "groupTen": "_10'"
} as const;

export const REST_SYMBOLS_BY_FAMILY = {
  "wholeOr16th": "m",
  "halfOr32nd": "u",
  "quarterOr64th": "v",
  "eighthOr128th": "x"
} as const;

export const TIE_SYMBOLS = {
  "single": "@c",
  "chord": ".c"
} as const;

export function accidentalBrf(accidental: ExplicitAccidental): string {
  const token = ACCIDENTAL_SYMBOLS[accidental];
  if (typeof token !== "string") fail(`unsupported accidental ${accidental}`);
  return token;
}

export function encodeAtomicChord(input: AtomicChordInput): BrailleEmission {
  if (input.intervals.length === 0) fail("atomic chord requires at least one interval member");
  const written = encodeAtomicNote({ ...input.writtenNote, tie: false }).brf;
  let brf = written;
  for (const member of input.intervals) {
    if (member.accidental) brf += accidentalBrf(member.accidental);
    brf += intervalBrf(member.diatonicInterval);
  }
  if (input.tieAll) brf += tieBrf("chord");
  return emission(brf);
}

export function encodeAtomicNote(input: AtomicNoteInput): BrailleEmission {
  const dots = input.augmentationDots ?? 0;
  assertAugmentationDots(dots);
  let brf = "";
  if (input.tripletStart) brf += tripletIndicatorBrf();
  if (input.accidental) brf += accidentalBrf(input.accidental);
  if (input.includeOctave !== false) brf += octavePrefixBrf(input.scientificOctave);
  brf += noteCellBrf(input.step, input.value);
  brf += "'".repeat(dots);
  if (input.tie) brf += tieBrf("single");
  return emission(brf);
}

export function encodeAtomicRest(input: AtomicRestInput): BrailleEmission {
  const dots = input.augmentationDots ?? 0;
  assertAugmentationDots(dots);
  let brf = "";
  if (input.tripletStart) brf += tripletIndicatorBrf();
  brf += restCellBrf(input.value);
  brf += "'".repeat(dots);
  return emission(brf);
}

export function encodeKeySignature(sharpsFlats: number): BrailleEmission {
  return emission(keySignatureBrf(sharpsFlats));
}

export function encodeSimpleMeter(numerator: number, denominator: number): BrailleEmission {
  return emission(simpleMeterBrf(numerator, denominator));
}

export function intervalBrf(interval: 2 | 3 | 4 | 5 | 6 | 7 | 8): string {
  const token = INTERVAL_SYMBOLS[String(interval) as keyof typeof INTERVAL_SYMBOLS];
  if (typeof token !== "string") fail(`unsupported diatonic interval ${interval}`);
  return token;
}

export function keySignatureBrf(sharpsFlats: number): string {
  if (!Number.isInteger(sharpsFlats) || sharpsFlats < -7 || sharpsFlats > 7) {
    fail(`key signature sf must be an integer in -7..7, got ${sharpsFlats}`);
  }
  if (sharpsFlats === 0) return "";
  const count = Math.abs(sharpsFlats);
  const sign = sharpsFlats > 0 ? ACCIDENTAL_SYMBOLS.sharp : ACCIDENTAL_SYMBOLS.flat;
  if (count <= 3) return sign.repeat(count);
  return `#${upperCellNumberBrf(count)}${sign}`;
}

export function noteCellBrf(step: MusicNoteName, value: MusicValue): string {
  const family = VALUE_TO_FAMILY[value];
  const mapping = NOTE_SYMBOLS_BY_FAMILY[family];
  const token = mapping[step];
  if (typeof token !== "string") fail(`unsupported note ${step} ${value}`);
  return token;
}

export function octavePrefixBrf(scientificOctave: number): string {
  if (!Number.isInteger(scientificOctave) || scientificOctave < 0 || scientificOctave > 8) {
    fail(`scientificOctave must be an integer in 0..8, got ${scientificOctave}`);
  }
  if (scientificOctave === 0) return OCTAVE_PREFIXES.sub;
  if (scientificOctave === 8) return OCTAVE_PREFIXES.super;
  const token = OCTAVE_PREFIXES[String(scientificOctave) as keyof typeof OCTAVE_PREFIXES];
  if (typeof token !== "string") fail(`missing octave token for scientific octave ${scientificOctave}`);
  return token;
}

export function restCellBrf(value: MusicValue): string {
  const family = VALUE_TO_FAMILY[value];
  const token = REST_SYMBOLS_BY_FAMILY[family];
  if (typeof token !== "string") fail(`unsupported rest ${value}`);
  return token;
}

export function simpleMeterBrf(numerator: number, denominator: number): string {
  if (!Number.isInteger(numerator) || numerator < 1 || numerator > 99) {
    fail(`meter numerator must be an integer in 1..99, got ${numerator}`);
  }
  if (!(METER_DENOMINATORS as readonly number[]).includes(denominator)) {
    fail(`unsupported simple meter denominator ${denominator}`);
  }
  return `#${upperCellNumberBrf(numerator)}${String(denominator)}`;
}

export function tieBrf(kind: TieKind): string {
  if (kind === "single") return TIE_SYMBOLS.single;
  if (kind === "chord") return TIE_SYMBOLS.chord;
  fail(`unsupported tie kind ${String(kind)}`);
}

export function tripletIndicatorBrf(): string {
